-- Sólo contenido editorial. No repite operaciones ni cambia asignaciones de personal.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES('conceptos-por-empleado-bono-confirmado','Conceptos por empleado: asignar, cambiar y cancelar un bono','Personal',
'Asigna un concepto habitual con importe fijo, revisa confirmaciones, filtros y Excel, programa otro importe y cancela el cambio futuro para restaurar la vigencia anterior. No genera nómina ni mueve dinero.',
'Administrador institucional identificado, con permisos de Empleados, Datos laborales y administración salarial; además Guía de procesos para consultar. No concede accesos. El recorrido de Bruce ya está concluido: consultar esta guía no requiere repetir altas, cambios ni cancelaciones. No alterar su sueldo base ni datos laborales.',
'Bruce Wayne · DOC-PRUEBA-02; BON-PUNT-TEST · Bono de puntualidad de prueba, Percepción/Habitual. Resultado final confirmado el 22/10/2026: $500 MXN desde 01/01/2027 sin fecha de fin, Próxima; aumento de $600 desde 01/02/2027 sin fecha de fin, Cancelada. El estado Próxima corresponde a la fecha del ensayo, anterior a enero de 2027.',1,DATE '2026-10-22','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo IN ('EMPLEADO_LEER','EMPLEADO_LABORAL_LEER','CONDICION_SALARIAL_ADMINISTRAR') WHERE g.slug='conceptos-por-empleado-bono-confirmado';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.n,v.t,'Administración',v.m,v.i,v.e,v.r,v.p,v.u FROM guia_proceso g CROSS JOIN (VALUES
(1,'Revisar empleado y concepto sin repetir catálogos','Administración → Personal y nómina → Empleados y Conceptos de nómina',
'1. Inicia sesión con administrador institucional autorizado y abre Personal y nómina → Empleados. 2. Busca Bruce Wayne, código DOC-PRUEBA-02, abre su expediente y confirma actividad, situación laboral ACTIVO y fecha de ingreso 01/10/2026. 3. Entra a Personal y nómina → Conceptos de nómina, localiza BON-PUNT-TEST y comprueba Percepción, Habitual y Activo; ya existe, no lo crees nuevamente. 4. Abre Personal y nómina → Conceptos por empleado; si los registros del ensayo ya existen, consulta su detalle sin repetir operaciones.',
'Catálogo describe el concepto; Conceptos por empleado asigna importe y vigencia. El sueldo base sigue en Asignaciones laborales, no se captura aquí.',
'Empleado y concepto identificados; no se modifican salarios, jornadas, planteles, usuarios ni clases.',
'El ensayo está confirmado. No reactivar ni cancelar registros sólo por leer esta guía. Un concepto ocasional no aparece en la ayuda de captura porque se resolverá al preparar una nómina específica.','/admin/conceptos-empleado'),
(2,'Capturar el bono habitual de 500','Administración → Personal y nómina → Conceptos por empleado → Asignar concepto',
'1. Para un ensayo nuevo autorizado, pulsa Asignar concepto; en Empleado enfoca el input sin escribir para ver hasta diez opciones, o escribe Bru desde tres caracteres y selecciona Bruce Wayne de la lista. 2. En Concepto habitual enfoca para ver opciones, o escribe BON y selecciona BON-PUNT-TEST; espera la consulta que muestra moneda, tipo y efecto y habilita Revisar asignación. 3. Captura Importe fijo por nómina 500.00, Inicio de vigencia 01/01/2027 y deja Último día de vigencia vacío. 4. Escribe el motivo Bono habitual de prueba desde enero de 2027, sin generar nómina.; comprueba que el efecto sea Suma al empleado antes de revisar.',
'Empleado DOC-PRUEBA-02 · Bruce Wayne; BON-PUNT-TEST; $500.00 MXN; inicio 01/01/2027 y sin fin.',
'Captura completa, seleccionada por ID y preparada para confirmar; todavía no existe una asignación nueva por escribir los datos.',
'Si ya existe el bono de 500 no vuelvas a guardarlo. Importe fijo por nómina no es porcentaje ni una cantidad mensual que se divida automáticamente; elegibilidad y prorrateos se definirán con la preparación de nómina.','/admin/conceptos-empleado/nuevo'),
(3,'Cancelar el resumen y después confirmar el alta','Administración → Personal y nómina → Conceptos por empleado → Asignar concepto → Revisar asignación',
'1. Pulsa Revisar asignación para abrir el modal; revisa empleado, concepto, importe de 500, moneda, inicio 01/01/2027, fin vacío, efecto y motivo. 2. Pulsa Cancelar dentro del modal: sólo debe cerrar el resumen y conservar los campos, sin guardar. 3. Vuelve a pulsar Revisar asignación y, cuando todo coincida, pulsa Confirmar y guardar. 4. Comprueba que abre el detalle con aviso de asignación registrada, sin nómina generada ni movimiento financiero.',
'Cancelar del modal conserva captura. Cancelar del formulario regresa al listado sin guardar; son acciones diferentes.',
'Un único bono guardado al confirmar, no al revisar o cancelar.',
'La rueda del mouse no incrementa el campo monetario de texto. Al quitar foco se presenta como moneda; el servidor recibe el decimal. No confirmar el ensayo ya existente para documentarlo.','/admin/conceptos-empleado'),
(4,'Comprobar resumen e historial del bono de 500','Administración → Personal y nómina → Conceptos por empleado → Ver → Resumen e Historial',
'1. Desde el listado localiza el bono de 500 de Bruce y pulsa Ver. 2. En Resumen comprueba concepto histórico, Percepción, Suma al empleado, importe de 500 MXN, inicio 01/01/2027 y Sin fecha de fin. 3. Comprueba estado Próxima si la fecha de consulta es anterior al inicio; no significa que ya se haya pagado. 4. Abre Historial para consultar fecha, usuario y motivo del registro y después pulsa Volver al listado.',
'Próxima indica vigencia futura; Vigente y Anterior dependen de la fecha local de la institución. No son estados de una nómina pagada.',
'Datos ordenados por pestañas e historial identificable, sin otro sueldo base ni egreso.',
'Código, nombre, tipo e importe de esta asignación son históricos. Editar el catálogo no debe reescribirlos; para otro importe se programa otra vigencia.','/admin/conceptos-empleado'),
(5,'Filtrar, exportar y volver sin perder la búsqueda','Administración → Personal y nómina → Conceptos por empleado → Filtros y Exportar Excel',
'1. En el listado selecciona Bruce desde la ayuda Empleado y BON-PUNT-TEST desde Concepto; ambas muestran hasta diez al foco y buscan desde tres caracteres. 2. Elige Estado de la vigencia Próximas, Tipo de concepto Percepción, Desde 01/01/2027 y Hasta 31/01/2027, con Texto adicional vacío; pulsa Aplicar filtros. 3. Comprueba sólo el bono de 500 y pulsa Exportar Excel: debe respetar esos mismos filtros, importe, moneda y fechas dd/MM/yyyy. 4. Abre Ver y pulsa Volver al listado para confirmar que conserva criterios y página; la × limpia sólo una selección y Limpiar restablece todos.',
'El rango busca vigencias que coincidan con el intervalo, no la fecha de creación. La etiqueta concatena código y nombre, pero la selección filtra por ID.',
'Pantalla y Excel coincidentes, sin perder el contexto al consultar el detalle.',
'Si escribes texto sin seleccionar una sugerencia, debe pedir selección o limpiar el campo; no debe mostrar todos inadvertidamente. Para encontrar una cancelada cambia el estado a Canceladas o Todas.','/admin/conceptos-empleado'),
(6,'Evitar asignaciones duplicadas y validar la captura','Administración → Personal y nómina → Conceptos por empleado → Asignar concepto',
'1. Sólo en prueba autorizada, intenta asignar al mismo Bruce el mismo BON-PUNT-TEST por 500 desde 01/01/2027 sin fin y motivo Duplicado que no debe guardarse. 2. Revisa y confirma el modal: debe impedirlo por vigencias superpuestas, conservar la captura y no crear otro bono. 3. Comprueba que obligatorios vacíos, importe cero o negativo, más de dos decimales, fecha pasada o fin anterior al inicio impidan guardar. 4. Sal con Cancelar del formulario y regresa al listado para comprobar que permanece sólo la asignación original.',
'Una misma pareja empleado/concepto no puede tener dos vigencias activas superpuestas. Conceptos diferentes sí pueden coexistir.',
'Validaciones sin duplicar la asignación ni modificar su importe original.',
'Esta guía documenta el recorrido aceptado, no una auditoría exhaustiva de todos los accesos o carreras. Las pruebas de dos pestañas y terminar una vigente son escenarios independientes; no se ejecutan sobre este cierre sólo para consultar instrucciones.','/admin/conceptos-empleado/nuevo'),
(7,'Programar aumento para febrero con fecha explícita','Administración → Personal y nómina → Conceptos por empleado → Ver del bono de 500 → Gestión → Programar cambio',
'1. Entra al listado, localiza el bono de 500 de Bruce y pulsa Ver → Gestión → Programar cambio. 2. Comprueba empleado y concepto protegidos, aviso separado de los inputs y tarjeta Referencia de la asignación anterior con importe de 500, inicio 01/01/2027 y fin vacío. 3. Captura importe de 600.00 y elige Inicio del nuevo importe 01/02/2027, que significa 1 de febrero; la fecha se presenta vacía para elegirla, no propone automáticamente el día siguiente. 4. Deja fin vacío, captura motivo Aumento de bono de prueba desde febrero de 2027., pulsa Revisar cambio y confirma después de revisar los datos.',
'01/02/2027 es 1 de febrero; 02/01/2027 es 2 de enero. El nuevo inicio debe ser posterior a hoy y al inicio anterior, dentro de su vigencia.',
'Nueva asignación 600 desde 01/02/2027; no se sobrescribe el importe histórico 500.',
'No se intercalan cambios cuando existe una programación posterior. Si el formulario cambió en otra pestaña, recarga y revisa antes de confirmar; no vuelvas a enviar una pantalla atrasada.','/admin/conceptos-empleado'),
(8,'Revisar las dos vigencias antes de cancelar','Administración → Personal y nómina → Conceptos por empleado → Listado y Ver',
'1. Vuelve al listado de Conceptos por empleado y conserva empleado Bruce y concepto BON-PUNT-TEST; cambia Estado de la vigencia a Todas. 2. Comprueba bono de 500 con inicio 01/01/2027 y fin 31/01/2027. 3. Comprueba aumento de 600 con inicio 01/02/2027 y Sin fecha de fin; ambos son Próxima durante la fecha del ensayo, anterior a enero de 2027, antes del inicio programado. 4. Abre Ver de cada uno para revisar sus importes y motivos históricos sin modificarlos.',
'La vigencia de 500 termina el día previo al inicio de 600. No se aplican 500 y 600 a la vez ni se crea un pago por programarlos.',
'Dos filas históricas claras, sin superposición del mismo concepto.',
'Si ya estás consultando el resultado final confirmado, el bono de 500 tendrá fin vacío y el de 600 estará Cancelada: eso es correcto después del paso siguiente; no hay que reconstruir la situación intermedia.','/admin/conceptos-empleado'),
(9,'Cancelar el aumento futuro y conservar su historial','Administración → Personal y nómina → Conceptos por empleado → Ver del bono de 600 → Gestión',
'1. Desde el listado pulsa Ver del registro 600 de febrero y abre Gestión; ubica Cancelar programación futura. 2. Captura motivo Cancelar aumento de prueba; conservar bono de 500 pesos. y pulsa Revisar cancelación. 3. En el modal pulsa primero Cancelar: debe cerrar el resumen sin cancelar la programación ni perder el motivo. 4. Vuelve a revisar y confirma la cancelación; comprueba que el registro 600 queda Cancelada y se restaura el fin anterior del bono de 500 cuando corresponde.',
'Cancelar sólo la última programación que aún no inicia. Conserva fechas, importe, usuario y motivo; no borra filas ni devuelve dinero.',
'Aumento 600 cancelado con trazabilidad, bono de 500 restaurado en la misma operación.',
'Cancelar dentro del modal no ejecuta la operación. El botón que confirma sí cancela la programación futura, no el concepto del catálogo ni el expediente del empleado. No cancelar también el bono de 500.','/admin/conceptos-empleado'),
(10,'Confirmar cierre y siguiente etapa sin repetir operaciones','Administración → Personal y nómina → Conceptos por empleado → Filtros → Ver → Historial',
'1. En el listado filtra Bruce y BON-PUNT-TEST con Estado Todas y sin fechas que oculten registros. 2. Comprueba el resultado final reportado:500 MXN desde 01/01/2027, Sin fecha de fin, Próxima;600 desde 01/02/2027, Sin fecha de fin, Cancelada. 3. En Ver → Historial consulta el motivo de cancelación y la restauración; el estado Cancelada impide aplicar 600 aunque su fin continúe vacío. 4. Conserva este cierre y consulta la guía sin volver a asignar o cancelar; el siguiente trabajo es analizar calendarios y preparación de nómina, todavía sin calcular o pagar.',
'Resultado confirmado por el propietario 22/10/2026: bono de 500 programado y aumento de 600 cancelado. No hubo generación de nómina ni modificación de cuentas por estas operaciones.',
'Recorrido cerrado y documentado; se conserva la asignación original y el historial del cambio cancelado.',
'Próxima cambiará a Vigente al llegar enero 2027 según la fecha institucional; Cancelada no se reactiva por el paso del tiempo. No duplicar sueldo base ni asumir impuestos, préstamos, porcentajes o conceptos ocasionales antes de diseñar preparación de nómina.','/admin/conceptos-empleado')
)v(n,t,m,i,e,r,p,u) WHERE g.slug='conceptos-por-empleado-bono-confirmado';

UPDATE guia_proceso_paso SET precaucion='El catálogo ya está confirmado y su siguiente recorrido también: consulta Guía de procesos → Personal → Conceptos por empleado para asignación, cambio de importe y cancelación futura. No repetir altas ni cambiar el sueldo base. Después se analizarán calendarios y preparación de nómina; no se generan pagos todavía.'
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='conceptos-nomina-catalogo-confirmado') AND numero=10;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-22' WHERE slug='conceptos-nomina-catalogo-confirmado';
